import numpy as np
for label in ['initial','inspect_after','cycle_inspect']:
 d=np.load(f'/app/runs/{label}/depth_topview.npy')[0].astype(float)
 for th in [1.46,1.48,1.485]:
  m=d<th
  # nonzero pixel bboxes around relevant area x 100:210 y40:110
  y,x=np.where(m[40:110,100:210]); x=x+100; y=y+40
  print(label,th,len(x), (x.min(),x.max(),y.min(),y.max()) if len(x) else None)
  # components via 8-connected BFS
  a=m[40:110,100:210]; seen=np.zeros_like(a,bool); comps=[]
  for yy,xx in zip(*np.where(a)):
   if seen[yy,xx]: continue
   stack=[(yy,xx)];seen[yy,xx]=1; ps=[]
   while stack:
    cy,cx=stack.pop();ps.append((cx+100,cy+40))
    for dy in [-1,0,1]:
     for dx in [-1,0,1]:
      ny,nx=cy+dy,cx+dx
      if 0<=ny<a.shape[0] and 0<=nx<a.shape[1] and a[ny,nx] and not seen[ny,nx]:
       seen[ny,nx]=1;stack.append((ny,nx))
   if len(ps)>=3:
    ar=np.array(ps);comps.append((len(ps),ar[:,0].min(),ar[:,0].max(),ar[:,1].min(),ar[:,1].max(),ar[:,0].mean(),ar[:,1].mean()))
  print(sorted(comps,reverse=True)[:10])
PY

